#include <fstream>
#include <iostream>
#include <stdio.h>
#include <math.h>

using namespace std;

struct dot
{
	int x;
	int y;
} a, b, c;

bool onOneLine(float x1, float x2, float x3, float y1, float y2, float y3)
{
	double d1, d2, d3;
	d1 = (pow((x1 - x2), 2) + pow((y1 - y2), 2), 1.0 / 2.0);
	d2 = (pow((x1 - x3), 2) + pow((y1 - y3), 2), 1.0 / 2.0);
	d3 = (pow((x2 - x3), 2) + pow((y2 - y3), 2), 1.0 / 2.0);

	if (d1 + d2 == d3 || d1 + d3 == d2 || d2 + d3 == d1)
		return false;
	return true;
}

int main()
{
	ifstream input;
	ofstream out;

	out.open("standard.output");
	input.open("standard.input");

	input >> a.x;
	input >> a.y >> b.x >> b.y >> c.x >> c.y;
	input.close();

	if (onOneLine(a.x, a.y, b.x, b.y, c.x, c.y))
	{
		out << "TOWARDS";
		out.close();
		return 0;
	}

	if ((c.x > a.x) && (c.y > a.y))
	{
		out << "RIGHT";
		out.close();
		return 0;
	}

	out << "LEFT";
	out.close();
	return 0;
}

