#include <fstream>
using namespace std;

struct Point {
    long long x, y;
};

int main() {
    ifstream input("standard.input");
    ofstream output("standard.output");

    Point a, b, c;
    input >> a.x >> a.y >> b.x >> b.y >> c.x >> c.y;

    long long cross = (b.x - a.x) * (c.y - a.y)
                    - (b.y - a.y) * (c.x - a.x);

    if (cross == 0)
        output << "TOWARDS";
    else if (cross < 0)
        output << "RIGHT";
    else
        output << "LEFT";

    return 0;
}

